function evPeerStart(ev){
  var p=G.player, id=ev.id;
  try{ evSound(id,'live'); }catch(_es4){}   // v16.xx (evalert)

// v16.xx (evalert), HIS ANSWER (2026-10-14): the raid events, "1-2 per raid. He did not know what the events were, so he never noticed them. Make each one obvious when it starts: a clear alert with its name, a map and
// minimap mark, a distinct sound." The alert with the name and a short detail (and the seconds to go) was already said, and the pinned mark with its name and the count is on the minimap and the sector map; what was
// missing was the SOUND: every event started in silence. Each event has a signature of its own now, on the sting bus, when its warning begins: orbital debris a falling siren, the machine convoy two low horn calls, the
// bounty pillager three tolling bells, the coolant rupture an icy chime over a hiss, the Overseer rampage a deep growl; and a short double stab when the event goes live. Player 2 hears the same in his window.
var EV_SND={
  debris:[[0,1200,500,0.7,'sawtooth',0.05],[0.25,1000,420,0.7,'sawtooth',0.04],[0.5,800,350,0.6,'square',0.03]],
  convoy:[[0,147,147,0.45,'sawtooth',0.06],[0.55,147,196,0.5,'sawtooth',0.06]],
  bounty:[[0,659,659,0.9,'sine',0.06],[0,1318,1318,0.5,'sine',0.02],[0.45,523,523,0.9,'sine',0.06],[0.9,392,392,1.2,'sine',0.06]],
  cool:[[0,2093,2093,0.6,'sine',0.03],[0.08,2637,2637,0.6,'sine',0.025],[0.16,3136,3136,0.8,'sine',0.02],[0,400,300,1.0,'triangle',0.025]],
  rampage:[[0,62,40,1.2,'sawtooth',0.10],[0.1,93,58,1.1,'square',0.045],[0.5,55,38,0.9,'sawtooth',0.07]],
  live:[[0,880,880,0.12,'square',0.05],[0.16,880,880,0.12,'square',0.05]]
};
function evSound(id,phase){
  var n=(phase==='live')?EV_SND.live:EV_SND[id];
  if(!n||typeof styTone!=='function') return false;
  return styTone(n);
}
// FLOW-MODULE-END (the next flow builds add their code above this line)

